fn inl_DBGEXIInit_unfused<'a>(ctx: &'a Ctx) {
    let _ = fns::__OSMaskInterrupts(ctx, (0x18000_i32 as u32));
    (Handle::add((ptr::<Val<'a, u32>>(ctx, 0xcc006800_u32 as u32)), 10_i32)).set((0_i32 as u32));
}

